type ReadinessOperation = 'open' | 'catalog' | 'readiness';
type ReadinessPhase = 'before-await' | 'after-await' | 'returned' | 'threw';
const TEAM_TOKEN_ENV = 'LEGACY_AGENT_HOST_TEAM_MCP_TOKEN';

/** Captured native flags only. RPC, native configuration acceptance and discovery belong to D. */
export function codexLaunchArguments(context: MemberProviderContext): string[] {
  const required = createTeamMcpTools(context.connection)
    .list()
    .map((tool) => tool.name);
  const settings: Record<string, string | number | boolean | string[]> = {
    'mcp_servers.team.enabled': true,
    'mcp_servers.team.url': context.endpoint.url,
    'mcp_servers.team.bearer_token_env_var': TEAM_TOKEN_ENV,
    'mcp_servers.team.enabled_tools': required,
    'mcp_servers.team.startup_timeout_sec': Math.ceil(context.profile.limits.timeoutMs / 1000),
    'mcp_servers.team.tool_timeout_sec': Math.ceil(context.profile.limits.timeoutMs / 1000),
  };
  for (const name of required) {
    // Pinned native 0.162.0 mode for our already-authorized captured Team tools.
    settings[`mcp_servers.team.tools.${name}.approval_mode`] = 'approve';
  }
  return [
    ...codexModelOptionArgs(
      context.profile.provider === 'codex'
        ? {
            ...(context.profile.nativeOptions.reasoningEffort === undefined
              ? {}
              : { reasoningEffort: context.profile.nativeOptions.reasoningEffort }),
            ...(context.profile.nativeOptions.fastMode === undefined
              ? {}
              : { fastMode: context.profile.nativeOptions.fastMode }),
          }
        : {}
    ),
    ...(context.profile.provider === 'codex' && context.profile.capturedMcpServers !== undefined
      ? codexMcpPolicyArgs(codexMcpPolicy(context.profile, context.endpoint, required)!)
      : []),
    ...Object.entries(
      context.profile.provider === 'codex' && context.profile.capturedMcpServers !== undefined
        ? {}
        : settings
    ).flatMap(([key, value]) => ['-c', `${key}=${JSON.stringify(value)}`]),
    'app-server',
    '--listen',
    'stdio://',
    ...captureCodexExtraArgs(context.profile.extraArgs),
  ];
}

/** Selected Codex process custody plus public D; no native protocol implementation. */
export function createCodexMemberProvider(
  context: MemberProviderContext,
  options: {
    readCatalog?: typeof readCodexMcpCatalog;
    /** Controlled byte streams in tests; production always uses captured handle custody. */
    createProcess?(profile: CodexMemberProfile, canAllocate: () => boolean): CapturedProcessPort;
  } = {}
): MemberProvider {
  const { profile } = context;
  const evidence = context.codexEvidence;
  const readinessObservation = (() => {
    let diagnostic: ReturnType<typeof channel> | undefined;
    let identity: { schemaVersion: 1; bindingDigest: string; sourceId: string; sourceRevision: string } | undefined;
    let sequence = 0, invocations = 0, disabled = false;
    try {
      diagnostic = channel('agent-teams.legacy-host.codex-readiness');
      const origin = context.processOrigin, binding = context.endpoint.binding;
      const sourceId = origin?.sourceId, sourceRevision = origin?.revision;
      if (origin?.origin.kind === 'runtime' && typeof sourceId === 'string' && /^[a-f0-9]{64}$/.test(sourceId) &&
          typeof sourceRevision === 'string' && /^[a-f0-9]{64}$/.test(sourceRevision)) {
        const { backendId, teamId, runId, memberId, generation } = binding;
        if ([backendId, teamId, runId, memberId, generation].every(value => typeof value === 'string'))
          identity = { schemaVersion: 1, bindingDigest: managementDigest({ backendId, teamId, runId, memberId, generation }), sourceId, sourceRevision };
      }
    } catch { disabled = true; }
    const limit = (): void => { try {
      if (!identity || disabled) return; disabled = true;
      if (diagnostic?.hasSubscribers) diagnostic.publish({ ...identity, limit: true });
    } catch { disabled = true; } };
    const publish = (invocation: number | undefined, operation: ReadinessOperation, phase: ReadinessPhase, result: boolean | null = null): void => { try {
      if (!identity || disabled || invocation === undefined) return;
      if (sequence >= 64) { limit(); return; }
      sequence++;
      if (diagnostic?.hasSubscribers) diagnostic.publish({ ...identity, sequence, invocation, operation, phase, result });
    } catch { disabled = true; } };
    const begin = (operation: ReadinessOperation): number | undefined => { try {
      if (!identity || disabled) return undefined;
      if (invocations >= 16) { limit(); return undefined; }
      const invocation = ++invocations; publish(invocation, operation, 'before-await'); return invocation;
    } catch { disabled = true; return undefined; } };
    return { begin, publish };
  })();
  if (profile.provider !== 'codex') throw new Error('Invalid Codex profile');
  qualifiedCodexProtocolRevision(profile.protocolRevision);
  if (!capturedMcpSourceCurrent(profile)) throw new Error('Captured MCP source changed');
  const extraArgs = captureCodexExtraArgs(profile.extraArgs);
  const policy = codexMcpPolicy(
    profile,
    context.endpoint,
    createTeamMcpTools(context.connection)
      .list()
      .map((tool) => tool.name)
  );
  const captured = {
    ...profile,
    ...(extraArgs.length ? { extraArgs: [...extraArgs] } : {}),
    environment: {
      ...profile.environment,
      [TEAM_TOKEN_ENV]: context.endpoint.bearerToken,
    },
  };
  const canAllocate = () => context.canAllocate() && capturedMcpSourceCurrent(profile);
  const canCapture = () =>
    (context.canCaptureRegisteredProcess?.() ?? context.canAllocate()) &&
    capturedMcpSourceCurrent(profile);
  const custody = (
    options.createProcess ??
    ((selected, canAllocate) =>
      new CapturedProcess(
        selected,
        canAllocate,
        context.processCustody,
        canCapture,
        undefined,
        context.retainedWindowsLaunch?.port(selected, canAllocate, canCapture, context.processOrigin)
      ))
  )(captured, canAllocate);
  let sealed = false;
  let ready = false;
  let allocated = false;
  const current = () =>
    !sealed && context.isCurrent() && custody.isRunning() && capturedMcpSourceCurrent(profile);
  const verifyCatalog = async (signal?: AbortSignal): Promise<boolean> => {
    if (!policy) return true;
    let invocation: number | undefined;
    const assertCurrent = () => {
      if (sealed || !context.isCurrent() || !capturedMcpSourceCurrent(profile))
        throw new Error('Captured MCP authority changed');
    };
    try {
      assertCurrent();
      invocation = readinessObservation.begin('catalog');
      const actual = await (options.readCatalog ?? readCodexMcpCatalog)(
        profile,
        assertCurrent,
        signal,
        capturedNativeProcessFactory(context.retainedWindowsLaunch, context.processOrigin)
      );
      readinessObservation.publish(invocation, 'catalog', 'after-await');
      assertCurrent();
      const matches = actual.digest === policy.catalog.digest;
      readinessObservation.publish(invocation, 'catalog', 'returned', matches);
      return matches;
    } catch {
      readinessObservation.publish(invocation, 'catalog', 'threw');
      return false;
    }
  };
  const required = createTeamMcpTools(context.connection)
    .list()
    .map((tool) => tool.name);
  const native = createCodexDriverFactory({
    capabilities: ['text', 'tools'],
    resolveConfiguration: async (request): Promise<CodexDriverConfig | undefined> => {
      if (
        allocated ||
        sealed ||
        !context.isCurrent() ||
        !context.canAllocate() ||
        JSON.stringify(request) !== JSON.stringify(context.request)
      )
        return undefined;
      if (!capturedMcpSourceCurrent(profile) || !(await verifyCatalog())) return undefined;
      if (sealed || !context.isCurrent() || !context.canAllocate()) return undefined;
      allocated = true;
      const args = codexLaunchArguments({ ...context, profile: captured });
      const child = custody.launch({
        command: profile.executable.path,
        args,
        cwd: profile.cwd,
      });
      observeMemberProcessStderr(child, context, args);
      return {
        binding: {
          tenantId: request.tenantId,
          projectId: request.projectId,
          sessionId: profile.sessionId,
          generation: profile.generation,
        },
        configRevision: profile.configRevision,
        protocolRevision: profile.protocolRevision,
        ...(evidence ? { capture: evidence } : {}),
        ...(context.attachments ? { attachments: context.attachments } : {}),
        trustedBinding: `${context.endpoint.binding.backendId}/${context.endpoint.binding.teamId}/${context.endpoint.binding.runId}/${profile.memberId}`,
        accountBinding: profile.accountBinding,
        transport: codexByteTransport(child),
        initialize: {
          clientInfo: { name: 'legacy-agent-host', version: '0.1.0' },
          capabilities: { experimentalApi: true },
        },
        ...(profile.nativeOptions.reasoningEffort === undefined
          ? {}
          : { turnParams: { effort: profile.nativeOptions.reasoningEffort } }),
        threadParams: {
          ...(profile.nativeOptions.fastMode === true ? { serviceTier: 'fast' } : {}),
          cwd: profile.cwd,
          model: profile.model,
          approvalPolicy: profile.nativeOptions.approvalPolicy,
          sandbox: profile.nativeOptions.sandbox,
          ...(profile.nativeOptions.modelProvider
            ? { modelProvider: profile.nativeOptions.modelProvider }
            : {}),
          developerInstructions: [context.instructions, profile.nativeOptions.developerInstructions]
            .filter(Boolean)
            .join('\n\n'),
        },
        requiredMcpTools: { team: required },
        ...(policy
          ? { mcpPolicy: policy, verifyMcpCatalog: verifyCatalog, runtimeMcpServer: 'team' }
          : {}),
        limits: { ...profile.limits },
        probe: async () => current(),
        confirmStopped: async () => {
          child.stdin.end();
          return custody.confirmStopped();
        },
      };
    },
    readCheckpoint: context.readCheckpoint,
  });
  const factory: DriverFactory = {
    async open(request) {
      let invocation: number | undefined;
      try {
        invocation = readinessObservation.begin('open');
        const opened = await native.open(request);
        readinessObservation.publish(invocation, 'open', 'after-await');
        const source = opened.driver;
        const driver: Session = {
          sessionRef: source.sessionRef,
          submit: (input) => source.submit(input),
          async *observe() {
            for await (const event of source.observe()) {
              yield event;
              context.onProgress();
            }
          },
          respondToInteraction: (reference, reply) => source.respondToInteraction(reference, reply),
          interrupt: (operation) => source.interrupt(operation),
          async checkReadiness() {
            const invocation = readinessObservation.begin('readiness');
            try {
              const proof = await source.checkReadiness();
              readinessObservation.publish(invocation, 'readiness', 'after-await');
              ready = proof.ok && current();
              readinessObservation.publish(invocation, 'readiness', 'returned', ready);
              return proof;
            } catch (error) {
              readinessObservation.publish(invocation, 'readiness', 'threw');
              throw error;
            }
          },
          checkpoint: () => source.checkpoint(),
          async close() {
            ready = false;
            evidence?.seal();
            return source.close();
          },
        };
        return { ...opened, driver };
      } catch {
        readinessObservation.publish(invocation, 'open', 'threw');
        // D may reject a checkpoint/configuration after transport allocation. Always clean up our handles.
        sealed = true;
        ready = false;
        evidence?.seal();
        custody.seal();
        await custody.confirmStopped();
        throw new Error('Codex member unavailable');
      }
    },
  };
  return {
    factory,
    ...(context.attachments
      ? {
          attachmentCapabilities: {
            images: NATIVE_IMAGE_MIME_TYPES.some(
              (mime) => context.attachments?.mimeTypes.includes(mime) === true
            ),
            documents: false,
            textFiles: false,
          },
        }
      : {}),
    ...(custody.captureRegisteredProcess
      ? { captureRegisteredProcess: custody.captureRegisteredProcess.bind(custody) }
      : {}),
    ...(profile.windowsBroker?.capability === 'service-scopes-v1' &&
        context.retainedWindowsLaunch && custody.prepareRegisteredWindowsProcess
      ? { prepareRegisteredWindowsProcess: custody.prepareRegisteredWindowsProcess.bind(custody) }
      : {}),
    isReady: () => ready && current(),
    initialContextEvidence: () =>
      ready && current()
        ? {
            kind: 'native-configuration',
            contextDigest: initialContextDigest(context.instructions),
            generation: context.endpoint.binding.generation,
            configRevision: context.request.configRevision,
          }
        : undefined,
    seal() {
      sealed = true;
      ready = false;
      evidence?.seal();
      custody.seal();
    },
    cleanup: () => custody.confirmStopped(),
  };
}

import { channel } from 'node:diagnostics_channel';
import { runtimeDigest } from '../runtime/identity.js';
import type { JsonValue } from '../contracts.js';
import type { RuntimeOwner } from '../runtime/RuntimeOwner.js';
import type { RuntimeBinding, RuntimeSessionRecord } from '../runtime/contracts.js';
import type { MemberEntry } from './MemberEntry.js';

const runtimeProjection = channel('agent-teams.legacy-host.runtime-projection');

/** Existing public Runtime snapshot omits private operation references and native identities. */
export function projectRuntimeMember(options: {
  entry: MemberEntry;
  record: RuntimeSessionRecord | undefined;
  binding: RuntimeBinding;
  runtime: Pick<RuntimeOwner, 'readSession'>;
  isCurrent(): boolean;
}): JsonValue {
  const { entry, record, binding } = options;
  const observed = options.runtime.readSession(binding);
  const bindingMatches = runtimeDigest(binding) === runtimeDigest(entry.binding);
  let recordReady: boolean | null = null, providerReady: boolean | null = null, ownerCurrent: boolean | null = null;
  const nativeReady =
    bindingMatches &&
    (recordReady = !!record?.nativeReady) &&
    (providerReady = !!entry.provider?.isReady()) &&
    (ownerCurrent = options.isCurrent());
  const captured =
    nativeReady &&
    observed.attached &&
    record !== undefined &&
    record.phase === 'allocated' &&
    record.custody === 'owned' &&
    !record.sealed &&
    runtimeDigest(record.binding) === runtimeDigest(binding) &&
    runtimeDigest(observed.record) === runtimeDigest(record);
  const attachmentCapabilities = captured ? entry.provider?.attachmentCapabilities : undefined;
  const sessionCommands = captured
    ? entry.profile.provider === 'codex'
      ? entry.team.connection.readRoster().members.some(member =>
          member.memberId === entry.profile.memberId && member.role === 'lead')
        ? [{ name: 'cost', description: 'Show reported token usage for this captured session' }]
        : []
      : entry.provider?.sessionCommands?.() ?? []
    : undefined;
  const value: JsonValue = {
    memberId: entry.profile.memberId,
    generation: binding.generation,
    phase: record?.phase ?? 'unopened',
    sealed: record?.sealed ?? false,
    custody: record?.custody ?? 'released',
    nativeReady,
    attached: observed.attached,
    ...(sessionCommands ? { sessionCommands: sessionCommands.map(({ name, description }) => ({ name, description })) } : {}),
    ...(attachmentCapabilities
      ? {
          attachmentCapabilities: {
            images: attachmentCapabilities.images,
            documents: attachmentCapabilities.documents,
            textFiles: attachmentCapabilities.textFiles,
          },
        }
      : {}),
    inputs: (record?.inputs ?? []).map((input) => ({
      inputId: input.intent.inputId,
      phase: input.phase,
      ...(input.terminal ? { terminal: input.terminal } : {}),
    })),
    interactions: (record?.interactions ?? []).map(({ operationRef: _operation, ...safe }) => safe),
    ...(record?.diagnostic ? { diagnostic: record.diagnostic } : {}),
  };
  try {
    if (runtimeProjection.hasSubscribers) runtimeProjection.publish({
      viewDigest: runtimeDigest(value), bindingMatches, recordReady, providerReady, ownerCurrent, nativeReady,
    });
  } catch { /* Private observation cannot replace the original public result. */ }
  return value;
}

import { normalizeRuntimeDelivery, findRuntimeInput, runtimeAdmission } from './runtimeDelivery.js';
import { prepareSessionOpen } from './prepareSessionOpen.js';
import { preparedInputProof, prepareRuntimeInput, recordContextEpoch } from './inputPreparation.js';
import { randomUUID } from 'node:crypto';

import type { RuntimeProcessOutput, RuntimeProviderActivity } from './providerActivityContracts.js';
import { RuntimeOwnerError } from './contracts.js';
import { CheckpointCoordinator } from './CheckpointCoordinator.js';
import { RuntimeActivityCoordinator } from './RuntimeActivityCoordinator.js';
import type {
  RuntimeActivityCursor,
  RuntimeActivityFeed,
  RuntimeActivitySnapshot,
  RuntimeConversationRead,
} from './activityContracts.js';
import {
  activeInput as active,
  emptySession,
  normalizeOpenConfig,
} from './sessionState.js';
import type {
  CheckpointAvailability,
  CheckpointReceipt,
  RestoreSessionRequest,
} from './checkpointContracts.js';
import { deliveryFingerprint, normalizeBinding, runtimeDigest } from './identity.js';
import type {
  RuntimeAdmission,
  RuntimeBinding,
  RuntimeDelivery,
  RuntimeInput,
  RuntimeOwnerOptions,
  RuntimeSessionRecord,
  RuntimeTransaction,
} from './contracts.js';
import type {
  Event,
  InteractionReply,
  OpenConfig,
  Session,
} from '@agent-teams/provider-session-contracts';

/** One durable technical dispatch owner; no Task policy or provider protocol implementation. */
export class RuntimeOwner {
  private readonly drivers = new Map<string, Session>();
  private readonly closes = new Map<string, Promise<RuntimeSessionRecord>>();
  private readonly controls = new Map<string, Set<Promise<unknown>>>();
  private readonly checkpoints: CheckpointCoordinator;
  private readonly activity: RuntimeActivityCoordinator;
  private readonly maxQueued: number;
  private readonly maxBytes: number;
  private readonly maxInteractions: number;
  private readonly interactionTtl: number;

  constructor(private readonly options: RuntimeOwnerOptions) {
    this.maxQueued = options.maxQueuedInputs ?? 128;
    this.maxBytes = options.maxInputBytes ?? 64 * 1024;
    this.maxInteractions = options.maxPendingInteractions ?? 32;
    this.interactionTtl = options.interactionTtlMs ?? 300_000;
    if (
      !options.profileId ||
      !options.hostIncarnation ||
      [this.maxQueued, this.maxBytes, this.maxInteractions, this.interactionTtl].some(
        (value) => !Number.isSafeInteger(value) || value <= 0
      )
    )
      throw new RuntimeOwnerError('invalid');
    this.activity = new RuntimeActivityCoordinator(options);
    this.checkpoints = new CheckpointCoordinator({
      store: this.activity,
      profileId: options.profileId,
      hostIncarnation: options.hostIncarnation,
      authorize: options.authorize,
      driver: (binding) => this.drivers.get(this.key(binding)),
      ...(options.checkpointBeforeClose ? { checkpointBeforeClose: options.checkpointBeforeClose } : {}),
      ...(options.checkpoints ? { storage: options.checkpoints } : {}),
      ...(options.checkpointIdleTimeoutMs === undefined
        ? {}
        : { idleTimeoutMs: options.checkpointIdleTimeoutMs }),
    });
  }

  readActivitySnapshot(binding: RuntimeBinding): RuntimeActivitySnapshot {
    return this.activity.snapshot(binding);
  }
  readActivityFeed(binding: RuntimeBinding, cursor: RuntimeActivityCursor): RuntimeActivityFeed {
    return this.activity.feed(binding, cursor);
  }
  /** Trusted composition read, under the original member authority and fence. */
  readConversation(binding: RuntimeBinding, mode: 'metadata' | 'messages', requireRecord = false): RuntimeConversationRead {
    return this.activity.conversation(binding, mode, requireRecord);
  }

  /** Private Host composition input, not exposed by RPC or the provider Session SPI. */
  observeProviderActivity(binding: RuntimeBinding, sessionRef: string, observation: RuntimeProviderActivity): void {
    this.activity.observeProviderActivity(normalizeBinding(binding), sessionRef, observation);
  }

  /** Original process observation, including startup before a Session reference exists. */
  observeProcessOutput(binding: RuntimeBinding, config: OpenConfig, observation: RuntimeProcessOutput, assertSourceCurrent: () => void): void {
    this.activity.observeProcessOutput(normalizeBinding(binding), normalizeOpenConfig(config, true), observation, assertSourceCurrent);
  }

  captureCheckpoint(input: {
    binding: RuntimeBinding;
    checkpointId: string;
  }, assertAuthority?: () => void): Promise<CheckpointReceipt> {
    return this.checkpoints.capture(input.binding, input.checkpointId, assertAuthority);
  }
  lookupCheckpoint(binding: RuntimeBinding, checkpointId: string): CheckpointReceipt {
    return this.checkpoints.lookup(binding, checkpointId);
  }
  readCheckpoints(binding: RuntimeBinding, nextConfig: OpenConfig): CheckpointAvailability {
    return this.checkpoints.readAvailable(binding, nextConfig);
  }
  /** Private DriverHost callback; never expose opaque checkpoint bytes through RPC. */
  readCheckpoint(reference: string, request: OpenConfig): Promise<unknown> {
    return this.checkpoints.readCheckpoint(reference, request);
  }
  validateRestoreSource(request: RestoreSessionRequest): void {
    this.checkpoints.validateRestoreSource(request);
  }
  async restoreSession(request: RestoreSessionRequest, assertAuthority?: () => void): Promise<RuntimeSessionRecord> {
    assertAuthority?.();
    const prepared = this.checkpoints.prepareRestore(request);
    return prepared.allocate
      ? this.allocate(prepared.record.binding, prepared.config, assertAuthority)
      : prepared.record;
  }

  readSession(binding: RuntimeBinding): {
    record: RuntimeSessionRecord | undefined;
    attached: boolean;
  } {
    binding = normalizeBinding(binding);
    return this.activity.fenced(binding, (tx) => {
      this.authorize(binding, 'read');
      return { record: tx.get(), attached: this.drivers.has(this.key(binding)) };
    });
  }

  /** Trusted composition custody inspection, like stopCapturedSession; never expose over RPC. */
  readCapturedSession(binding: RuntimeBinding): {
    record: RuntimeSessionRecord | undefined;
    attached: boolean;
  } {
    binding = normalizeBinding(binding);
    return this.activity.fenced(binding, (tx) => ({
      record: tx.get(),
      attached: this.drivers.has(this.key(binding)),
    }));
  }

  fingerprintDelivery(intent: RuntimeDelivery): string {
    return deliveryFingerprint(normalizeRuntimeDelivery(intent, this.maxBytes));
  }

  async openSession(
    input: { binding: RuntimeBinding; config: OpenConfig },
    assertAuthority?: () => void
  ): Promise<RuntimeSessionRecord> {
    return this.open(input, assertAuthority);
  }
  /** Private explicit fresh intent only. Ordinary open/restore retain unresolved-history guards. */
  async openFreshMemberSession(
    input: {
      sourceBinding: RuntimeBinding;
      binding: RuntimeBinding;
      config: OpenConfig;
    },
    assertAuthority: () => void
  ): Promise<RuntimeSessionRecord> {
    const source = normalizeBinding(input.sourceBinding),
      target = normalizeBinding(input.binding);
    if (
      typeof assertAuthority !== 'function' ||
      source.generation === target.generation ||
      ['backendId', 'teamId', 'runId', 'memberId'].some(
        (k) => source[k as 'memberId'] !== target[k as 'memberId']
      )
    )
      throw new RuntimeOwnerError('invalid');
    return this.open(input, assertAuthority, source);
  }
  private async open(
    input: { binding: RuntimeBinding; config: OpenConfig },
    assertAuthority?: () => void,
    freshSource?: RuntimeBinding
  ): Promise<RuntimeSessionRecord> {
    const binding = normalizeBinding(input.binding);
    const config = normalizeOpenConfig(input.config);
    const fingerprint = runtimeDigest({
      profileId: this.options.profileId,
      config,
    });
    const prepared = this.activity.fenced(binding, (tx) => {
      assertAuthority?.();
      this.authorize(binding, 'admit');
      return prepareSessionOpen({
        tx,
        binding,
        config,
        fingerprint,
        hostIncarnation: this.options.hostIncarnation,
        empty: () => this.empty(binding),
        ...(freshSource ? { freshSource } : {}),
        hasInFlight: (sibling) =>
          this.drivers.has(this.key(sibling)) ||
          !!this.controls.get(this.key(sibling))?.size ||
          this.closes.has(this.key(sibling)),
      });
    });
    if (!prepared.allocate) return prepared.record;
    return this.allocate(binding, config, assertAuthority);
  }

  private async allocate(
    binding: RuntimeBinding,
    config: OpenConfig,
    assertAuthority?: () => void
  ): Promise<RuntimeSessionRecord> {
    try {
      assertAuthority?.();
      const opened = await this.options.driverFactory.open(config, assertAuthority);
      this.drivers.set(this.key(binding), opened.driver);
      if (
        typeof opened.driver.sessionRef !== 'string' ||
        !opened.driver.sessionRef ||
        opened.driver.sessionRef.length > 1024
      )
        throw new RuntimeOwnerError('hold');
      let record = this.publish(binding, (current) => {
        if (!this.options.authorize(binding, 'admit') || !this.authorityCurrent(assertAuthority)) current.sealed = true;
        current.sessionRef = opened.driver.sessionRef;
        current.custody = 'owned';
        current.phase = current.sealed ? 'closing' : 'allocated';
      });
      void this.observe(binding, opened.driver);
      if (record.sealed) return await this.stopOwned(binding, true);
      const ready = await opened.driver.checkReadiness();
      record = this.publish(binding, (current) => {
        if (current.phase !== 'allocated' || current.sealed) return;
        current.nativeReady =
          ready.ok &&
          config.requiredCapabilities.every((capability) =>
            opened.capabilities.includes(capability)
          );
        if (!current.nativeReady) current.diagnostic = 'readiness-unavailable';
      });
      return record;
    } catch {
      return this.publish(binding, (current) => {
        if (current.phase === 'closed') return;
        current.phase = 'held';
        current.nativeReady = false;
        current.custody = 'unknown';
        current.diagnostic = 'open-unknown';
      });
    }
  }

  async admitDelivery(raw: RuntimeDelivery): Promise<RuntimeAdmission> {
    const intent = normalizeRuntimeDelivery(raw, this.maxBytes);
    return this.activity.fenced(intent.binding, (tx) => {
      this.authorize(intent.binding, 'admit', intent);
      const record = tx.get() ?? this.empty(intent.binding);
      const existing = findRuntimeInput(record, intent);
      if (existing) return runtimeAdmission(existing);
      if (record.sealed) return { inputId: intent.inputId, outcome: 'not_admitted' };
      if (
        record.inputs.filter((input) => input.phase === 'admitted' || active(input)).length >=
        this.maxQueued
      ) {
        throw new RuntimeOwnerError('busy');
      }
      const input: RuntimeInput = {
        intent,
        fingerprint: deliveryFingerprint(intent),
        operationRef: randomUUID(),
        phase: 'admitted',
      };
      record.inputs.push(input);
      tx.put(record, 'growth');
      return runtimeAdmission(input);
    });
  }

  async lookupDelivery(raw: RuntimeDelivery): Promise<RuntimeAdmission> {
    const intent = normalizeRuntimeDelivery(raw, this.maxBytes);
    return this.activity.fenced(intent.binding, (tx) => {
      this.authorize(intent.binding, 'read', intent);
      const record = tx.get();
      const input = record && findRuntimeInput(record, intent);
      return input ? runtimeAdmission(input) : { inputId: intent.inputId, outcome: 'not_admitted' };
    });
  }

  async cancelDelivery(raw: RuntimeDelivery): Promise<RuntimeAdmission> {
    const intent = normalizeRuntimeDelivery(raw, this.maxBytes);
    return this.activity.fenced(intent.binding, (tx) => {
      this.authorize(intent.binding, 'control', intent);
      const record = tx.get() ?? this.empty(intent.binding);
      let input = findRuntimeInput(record, intent);
      const unseen = !input;
      if (!input) {
        input = {
          intent,
          fingerprint: deliveryFingerprint(intent),
          operationRef: randomUUID(),
          phase: 'cancelled',
        };
        record.inputs.push(input);
      } else if (input.phase === 'admitted') input.phase = 'cancelled';
      tx.put(record, unseen ? 'growth' : undefined); // Includes unseen delivery IDs: a late outbox admission cannot resurrect them.
      return active(input)
        ? { inputId: input.intent.inputId, outcome: 'unknown' }
        : runtimeAdmission(input);
    });
  }

  async dispatchNext(binding: RuntimeBinding): Promise<RuntimeSessionRecord> {
    binding = normalizeBinding(binding);
    const claimed = this.activity.fenced(binding, (tx) => {
      const record = this.record(tx);
      const next = record.inputs.find((item) => item.phase === 'admitted');
      if (!this.options.authorize(normalizeBinding(binding), 'dispatch', next?.intent)) {
        for (const input of record.inputs) {
          if (
            input.phase === 'admitted' &&
            !this.options.authorize(normalizeBinding(binding), 'dispatch', input.intent)
          )
            input.phase = 'rejected';
        }
        tx.put(record);
        throw new RuntimeOwnerError('forbidden');
      }
      const driver = this.ownedDriver(record);
      if (
        record.sealed ||
        record.phase !== 'allocated' ||
        !record.nativeReady ||
        record.control ||
        record.checkpoints?.some((attempt) => attempt.status === 'capturing') ||
        record.inputs.some(active)
      ) {
        throw new RuntimeOwnerError('hold');
      }
      const input = record.inputs.find((item) => item.phase === 'admitted');
      if (!input) return { record, driver, input: undefined };
      if (!this.options.canDispatch?.(binding, input.intent)) throw new RuntimeOwnerError('hold');
      const selected = this.options.prepareInput?.(binding, {
        sessionRef: record.sessionRef!, inputId: input.intent.inputId, operationRef: input.operationRef,
        intentFingerprint: input.fingerprint, originalContent: input.intent.content, originalContentBytes: Buffer.byteLength(input.intent.content), epochs: structuredClone(record.contextEpochs ?? []),
        priorProofs: record.inputs.flatMap(value => value.preparation ? [preparedInputProof(value.preparation)] : []),
      });
      if (selected) input.preparation = prepareRuntimeInput(binding, input, selected, this.maxBytes);
      input.phase = 'claimed';
      tx.put(record); // The only submit claim; exact native supplement is durable before handoff.
      if (input.preparation) this.options.inputPrepared?.(binding, preparedInputProof(input.preparation));
      return { record, driver, input };
    });
    const input = claimed.input;
    if (!input) return claimed.record;
    let phase: RuntimeInput['phase'] = 'unknown';
    try {
      const reply = await claimed.driver.submit({
        inputId: input.intent.inputId,
        operationRef: input.operationRef,
        content: (input.preparation?.prefix ?? '') + input.intent.content,
        ...(input.intent.attachments?.length ? { attachments: input.intent.attachments } : {}),
      });
      if (
        reply.ok &&
        reply.value.inputId === input.intent.inputId &&
        reply.value.operationRef === input.operationRef
      )
        phase = 'consumed';
      else if (!reply.ok && reply.delivery === 'known-not-sent') phase = 'not-sent';
    } catch {
      /* Uncertain native handoff remains held, never a second submit. */
    }
    return this.publish(binding, (record) => {
      const current = record.inputs.find((item) => item.operationRef === input.operationRef);
      if (current?.phase === 'claimed') current.phase = phase;
    });
  }

  async interrupt(binding: RuntimeBinding, inputId: string, assertAuthority?: () => void): Promise<RuntimeSessionRecord> {
    binding = normalizeBinding(binding);
    const target = this.activity.fenced(binding, (tx) => {
      assertAuthority?.();
      this.authorize(binding, 'control');
      const record = this.record(tx);
      const driver = this.ownedDriver(record);
      const input = record.inputs.find((item) => item.intent.inputId === inputId);
      if (!input || !active(input)) return { record, driver, operationRef: undefined };
      if (record.control || record.closeClaimed) throw new RuntimeOwnerError('hold');
      record.control = { inputId, operationRef: input.operationRef, phase: 'pending' };
      tx.put(record);
      return { record, driver, operationRef: input.operationRef };
    });
    if (!target.operationRef) return target.record; // Late interrupt A cannot become interrupt B.
    const operationRef = target.operationRef;
    return this.trackControl(
      binding,
      Promise.resolve().then(async () => {
        let requested = false;
        try {
          const permitted = this.activity.fenced(binding, (tx) => {
            const record = this.record(tx);
            return !record.sealed && record.phase === 'allocated' &&
              record.control?.operationRef === operationRef &&
              record.control.phase === 'pending' &&
              record.inputs.some((input) => input.operationRef === operationRef && active(input)) &&
              this.options.authorize(binding, 'control') && this.authorityCurrent(assertAuthority);
          });
          if (permitted) requested = (await target.driver.interrupt(operationRef)).ok;
        } catch {
          /* held */
        }
        return this.publish(binding, (record) => {
          if (record.control?.operationRef !== operationRef) return;
          if (requested) delete record.control;
          else record.control.phase = 'unknown';
        });
      })
    );
  }

  async respondToInteraction(
    binding: RuntimeBinding,
    inputId: string,
    interactionRef: string,
    reply: InteractionReply,
    assertAuthority?: () => void
  ): Promise<RuntimeSessionRecord> {
    binding = normalizeBinding(binding);
    const target = this.activity.fenced(binding, (tx) => {
      assertAuthority?.();
      this.authorize(binding, 'control');
      const record = this.record(tx);
      const driver = this.ownedDriver(record);
      const interaction = record.interactions.find(
        (item) => item.interactionRef === interactionRef
      );
      const input = record.inputs.find((item) => item.intent.inputId === inputId);
      if (
        record.sealed ||
        !interaction ||
        interaction.inputId !== inputId ||
        interaction.kind !== reply.kind ||
        interaction.phase !== 'pending' ||
        interaction.expiresAt <= Date.now() ||
        !input ||
        !active(input)
      ) {
        throw new RuntimeOwnerError('hold');
      }
      interaction.phase = 'responding';
      tx.put(record);
      return driver;
    });
    return this.trackControl(
      binding,
      Promise.resolve().then(async () => {
        let accepted = false;
        const permitted = this.activity.fenced(binding, (tx) => {
          const current = this.record(tx);
          const interaction = current.interactions.find(
            (item) => item.interactionRef === interactionRef
          );
          const input = current.inputs.find((item) => item.intent.inputId === inputId);
          return (
            !current.sealed &&
            current.phase === 'allocated' &&
            !current.control &&
            interaction?.phase === 'responding' &&
            interaction.inputId === inputId &&
            interaction.kind === reply.kind &&
            interaction.expiresAt > Date.now() &&
            input !== undefined &&
            input.operationRef === interaction.operationRef &&
            active(input) &&
            this.options.authorize(binding, 'control') &&
            this.authorityCurrent(assertAuthority)
          );
        });
        try {
          if (permitted) accepted = (await target.respondToInteraction(interactionRef, reply)).ok;
        } catch {
          /* held */
        }
        return this.publish(binding, (record) => {
          const interaction = record.interactions.find(
            (item) => item.interactionRef === interactionRef
          );
          if (interaction?.phase === 'responding')
            interaction.phase = accepted ? 'resolved' : 'unknown';
        });
      })
    );
  }

  async stopSession(binding: RuntimeBinding, assertAuthority?: () => void): Promise<RuntimeSessionRecord> {
    return this.stopOwned(normalizeBinding(binding), false, assertAuthority);
  }

  /** Trusted composition shutdown only; never register as a business RPC or MCP tool. */
  async stopCapturedSession(binding: RuntimeBinding): Promise<RuntimeSessionRecord> {
    return this.stopOwned(normalizeBinding(binding), true);
  }

  private async stopOwned(
    binding: RuntimeBinding,
    capturedCleanup = false,
    assertAuthority?: () => void
  ): Promise<RuntimeSessionRecord> {
    const target = this.activity.fenced<{
      record: RuntimeSessionRecord;
      driver: Session | undefined;
      wait?: Promise<unknown>;
    }>(binding, (tx) => {
      assertAuthority?.();
      if (!capturedCleanup) this.authorize(binding, 'control');
      const saved = tx.get();
      const record = saved ?? (capturedCleanup ? this.empty(binding) : this.record(tx));
      const before = saved ? runtimeDigest(saved) : undefined;
      // Repeated cleanup preserves settled debt bytes without skipping any owned control/close work.
      const persistStop = () => { if (runtimeDigest(record) !== before) tx.put(record); };
      if (record.phase === 'closed' && record.sealed && !record.nativeReady &&
        !record.inputs.some(input => input.phase === 'admitted') &&
        !record.interactions.some(interaction => interaction.phase === 'pending'))
        return { record, driver: undefined };
      record.sealed = true;
      record.nativeReady = false;
      for (const input of record.inputs) if (input.phase === 'admitted') input.phase = 'cancelled';
      for (const interaction of record.interactions)
        if (interaction.phase === 'pending') interaction.phase = 'unknown';
      if (record.phase === 'closed') {
        persistStop();
        return { record, driver: undefined };
      }
      if (record.phase === 'unopened') {
        record.phase = 'closed';
        record.custody = 'released';
        persistStop();
        return { record, driver: undefined };
      }
      if (record.closeClaimed && !this.closes.has(this.key(binding))) {
        // A settled/abandoned close claim cannot become a new close or appear in flight again.
        record.phase = 'held';
        record.custody = 'unknown';
        persistStop();
        return { record, driver: undefined };
      }
      record.phase = 'closing';
      const driver =
        record.hostIncarnation === this.options.hostIncarnation
          ? this.drivers.get(this.key(binding))
          : undefined;
      if (!driver) {
        record.phase = 'held';
        record.custody = 'unknown';
      }
      const controls = this.controls.get(this.key(binding));
      if (!record.closeClaimed && controls?.size) {
        persistStop();
        return { record, driver: undefined, wait: Promise.allSettled([...controls]) };
      }
      if (record.closeClaimed || record.control?.phase === 'pending') {
        persistStop();
        return { record, driver: undefined };
      }
      if (driver) record.closeClaimed = true;
      persistStop();
      return { record, driver };
    });
    if (target.wait) {
      await target.wait;
      return this.stopOwned(binding, true, assertAuthority); // Continue this stop intent after its accepted controls settle.
    }
    if (!target.driver) return this.closes.get(this.key(binding)) ?? target.record;
    const driver = target.driver;
    const closing = (async () => {
      let confirmed = false;
      try {
        assertAuthority?.();
        this.checkpoints.captureBeforeClose(binding);
        assertAuthority?.();
        confirmed = (await driver.close()).cleanup === 'confirmed';
      } catch {
        /* custody retained */
      }
      const result = this.publish(binding, (record) => {
        record.phase = confirmed ? 'closed' : 'held';
        record.custody = confirmed ? 'released' : 'unknown';
        if (!confirmed) record.diagnostic = 'close-unknown';
        for (const input of record.inputs) if (active(input)) input.phase = 'unknown';
      });
      if (confirmed && this.drivers.get(this.key(binding)) === driver)
        this.drivers.delete(this.key(binding));
      return result;
    })();
    this.closes.set(this.key(binding), closing);
    void closing.then(
      () => this.closes.delete(this.key(binding)),
      () => this.closes.delete(this.key(binding))
    );
    return closing;
  }

  /** Explicit recovery command. Never adopts a driver or replays a claimed effect. */
  reconcileSession(binding: RuntimeBinding): RuntimeSessionRecord {
    binding = normalizeBinding(binding);
    return this.activity.fenced(binding, (tx) => {
      this.authorize(binding, 'control');
      const record = this.record(tx);
      if (
        record.phase === 'unopened' ||
        (record.phase === 'closed' && record.custody === 'released')
      )
        return record;
      if (
        record.hostIncarnation === this.options.hostIncarnation &&
        this.drivers.has(this.key(binding))
      )
        return record;
      record.phase = 'held';
      record.custody = 'unknown';
      record.nativeReady = false;
      for (const input of record.inputs) if (active(input)) input.phase = 'unknown';
      for (const interaction of record.interactions)
        if (interaction.phase !== 'resolved') interaction.phase = 'unknown';
      if (record.control) record.control.phase = 'unknown';
      tx.put(record);
      return record;
    });
  }

  private async observe(binding: RuntimeBinding, driver: Session): Promise<void> {
    let diagnostic: RuntimeSessionRecord['diagnostic'] = 'observe-ended';
    try {
      for await (const event of driver.observe()) {
        this.activity.observe(binding, driver.sessionRef, event, (record) => {
          this.applyEvent(record, event);
          this.checkpoints.signal(binding);
        });
      }
    } catch {
      diagnostic = 'observe-failed';
    }
    try {
      this.activity.fenced(binding, (tx) => {
        const record = this.record(tx);
        if (record.hostIncarnation !== this.options.hostIncarnation || record.phase === 'closed')
          return;
        record.diagnostic = diagnostic;
        record.nativeReady = false;
        for (const input of record.inputs) if (active(input)) input.phase = 'unknown';
        tx.put(record);
      });
    } catch {
      /* Store failures are not converted to successful outcomes or new dispatch. */
    }
  }

  private trackControl<T>(binding: RuntimeBinding, work: Promise<T>): Promise<T> {
    const key = this.key(binding);
    const pending = this.controls.get(key) ?? new Set<Promise<unknown>>();
    pending.add(work);
    this.controls.set(key, pending);
    const release = (): void => {
      pending.delete(work);
      if (!pending.size && this.controls.get(key) === pending) this.controls.delete(key);
    };
    void work.then(release, release);
    return work;
  }

  private applyEvent(record: RuntimeSessionRecord, event: Event): void {
    if (event.kind === 'compaction') { recordContextEpoch(record, event); return; }
    const input = record.inputs.find(
      (item) => item.intent.inputId === event.inputId && item.operationRef === event.operationRef
    );
    if (!input || !active(input)) return;
    if (event.kind === 'result') {
      if (event.outcome === 'unknown') input.phase = 'unknown';
      else {
        input.phase = 'terminal';
        input.terminal = event.outcome;
      }
      for (const interaction of record.interactions)
        if (interaction.inputId === input.intent.inputId && interaction.phase !== 'resolved')
          interaction.phase = 'unknown';
    } else if (event.kind === 'interaction' && !record.sealed) {
      if (record.interactions.some((item) => item.interactionRef === event.interactionRef)) return;
      if (
        record.interactions.filter((item) => ['pending', 'responding'].includes(item.phase))
          .length >= this.maxInteractions
      ) {
        record.nativeReady = false;
        return;
      }
      record.interactions.push({
        interactionRef: event.interactionRef,
        inputId: input.intent.inputId,
        operationRef: input.operationRef,
        kind: event.request.kind,
        expiresAt: Date.now() + this.interactionTtl,
        phase: 'pending',
      });
    }
  }

  private publish(
    binding: RuntimeBinding,
    mutate: (record: RuntimeSessionRecord) => void
  ): RuntimeSessionRecord {
    return this.activity.fenced(binding, (tx) => {
      const record = this.record(tx);
      mutate(record);
      tx.put(record);
      this.checkpoints.signal(binding);
      return record;
    });
  }
  private authorityCurrent(assertAuthority?: () => void): boolean {
    try { assertAuthority?.(); return true; }
    catch { return false; }
  }
  private authorize(
    binding: RuntimeBinding,
    action: 'read' | 'admit' | 'dispatch' | 'control',
    intent?: RuntimeDelivery
  ): void {
    if (!this.options.authorize(normalizeBinding(binding), action, intent))
      throw new RuntimeOwnerError('forbidden');
  }
  private ownedDriver(record: RuntimeSessionRecord): Session {
    const driver = this.drivers.get(this.key(record.binding));
    if (record.hostIncarnation !== this.options.hostIncarnation || !driver)
      throw new RuntimeOwnerError('hold');
    return driver;
  }
  private record(tx: RuntimeTransaction): RuntimeSessionRecord {
    const record = tx.get();
    if (!record) throw new RuntimeOwnerError('hold');
    return record;
  }
  private empty(binding: RuntimeBinding): RuntimeSessionRecord {
    return emptySession(binding, this.options.profileId, this.options.hostIncarnation);
  }
  private key(binding: RuntimeBinding): string {
    return runtimeDigest(normalizeBinding(binding));
  }

}

import { readCodexConfiguredMcpCatalog } from '@agent-teams/provider-implementations/codex';
import { CapturedProcess } from './CapturedProcess.js';
import type { CapturedProcessPort } from './CapturedProcess.js';
import type { CodexConfiguredMcpCatalog } from '@agent-teams/provider-implementations/codex';
import type { CodexMemberProfile } from '../../composition/runtimeProfile.js';

/** D owns native metadata decoding; Host retains only this original short-lived child handle. */
export async function readCodexMcpCatalog(
  profile: CodexMemberProfile,
  assertCurrent: () => void,
  signal?: AbortSignal,
  createProcess?: (selected: CodexMemberProfile, current: () => boolean) => CapturedProcessPort
): Promise<CodexConfiguredMcpCatalog> {
  assertCurrent();
  const current = () => {
    try {
      assertCurrent();
      return true;
    } catch {
      return false;
    }
  };
  const custody = createProcess ? createProcess(profile, current) : new CapturedProcess(profile, current);
  return readCodexConfiguredMcpCatalog(
    {
      cwd: profile.cwd,
      executablePath: profile.executable.path,
      environment: { ...profile.environment },
      timeoutMs: Math.min(profile.limits.timeoutMs, 180000),
      canRead: current,
      launch(request) {
        assertCurrent();
        const child = custody.launch({
          command: request.command,
          args: [...request.args],
          cwd: request.cwd,
          signal: request.signal,
        });
        const terminal = new Promise<{ exitCode: number | null; signal: string | null }>(
          (resolve) => {
            child.once('error', () => resolve({ exitCode: null, signal: 'spawn-error' }));
            child.once('close', (exitCode, signal) => resolve({ exitCode, signal }));
          }
        );
        return {
          async *read() {
            for await (const chunk of child.stdout) {
              if (!(chunk instanceof Uint8Array)) throw new Error('Codex catalog unavailable');
              yield chunk;
            }
          },
          terminal,
          async dispose() {
            child.stdin.end();
            return custody.confirmStopped();
          },
        };
      },
    },
    signal
  );
}

import type { DriverFactory, OpenConfig } from '@agent-teams/provider-session-contracts'
import { captureDriverConfig, selectedDriverCheckpoint } from './driver-config.ts'
import type { CodexDriverCheckpoint, CodexDriverConfig } from './driver-config.ts'
import { CodexDriverSession } from './driver-session.ts'

export type CodexDriverHost = {
  readonly resolveConfiguration: (request: OpenConfig) => Promise<CodexDriverConfig | undefined>
  readonly readCheckpoint: (reference: string, request: OpenConfig) => Promise<unknown>
  readonly capabilities: readonly string[]
}
const supported = new Set(['text', 'tools', 'usage', 'permission', 'interrupt', 'checkpoint', 'attachments'])

/** Native transport is caller-selected, exclusive to this binding and already under caller custody. */
export function createCodexDriverFactory(host: CodexDriverHost): DriverFactory {
  const capabilities = Object.freeze([...host.capabilities])
  if (capabilities.some(value => !supported.has(value)) || new Set(capabilities).size !== capabilities.length) {throw new Error('codex.driver.unsupported')}
  return { async open(request) {
    const selected = Object.freeze({ ...request, requiredCapabilities: Object.freeze([...request.requiredCapabilities]) })
    if (selected.requiredCapabilities.some(value => !capabilities.includes(value))) {throw new Error('codex.driver.unsupported')}
    let config: CodexDriverConfig
    try { const value = await host.resolveConfiguration(selected); if (!value) {throw new Error('missing');} config = captureDriverConfig(value, selected) }
    catch { throw new Error('codex.driver.invalid-config') }
    let restored: CodexDriverCheckpoint | undefined
    if (selected.checkpointRef !== undefined) {
      let checkpoint: unknown
      try { checkpoint = await host.readCheckpoint(selected.checkpointRef, selected) } catch { throw new Error('codex.driver.checkpoint-missing') }
      if (checkpoint === undefined) {throw new Error('codex.driver.checkpoint-missing')}
      restored = selectedDriverCheckpoint(checkpoint, config)
    }
    const driver = new CodexDriverSession(config, restored)
    const mandatoryNativeTools = Object.keys(config.requiredMcpTools ?? {}).length > 0 || config.mcpPolicy !== undefined
    try {
      if (!mandatoryNativeTools) {
        const ready = await driver.checkReadiness()
        if (!ready.ok) {throw new Error('codex.driver.' + ready.code)}
      }
      await driver.open(restored?.nativeThreadId)
    } catch { await driver.close(); throw new Error('codex.driver.open-failed') }
    // Thread-scoped discovery requires the owned native thread. No turn/work is
    // submitted until native mandatory tools and the Host probe both pass.
    if (mandatoryNativeTools) {
      const ready = await driver.checkReadiness()
      if (!ready.ok) { await driver.close(); throw new Error('codex.driver.' + ready.code) }
    }
    return { driver, capabilities }
  } }
}

import { randomUUID } from 'node:crypto'
import { CODEX_NEXT_PROMPT_SAMPLE_INSTRUCTION, supportsNativeCodexSampling, decodeCodexPromptSuggestion } from '../../../native-prompt-suggestions/adapters/codex-sample.ts'
import { eligibleNativeInput, offerNativeSuggestion } from '../../../native-prompt-suggestions/core/policy.ts'
import { CodexInputWindowCapture } from './input-window-capture.ts'
import type { CloseReceipt, Event, EventPayload, FailureCode, Handoff, Input, InteractionReply, Reply, Session } from '@agent-teams/provider-session-contracts'
import { bounded, deferred, EventFeed } from '../provider-session-io/io.ts'
import { CodexAppServerClient } from './app-server.ts'
import { driverCompatibility } from './driver-config.ts'
import type { CodexDriverCheckpoint, CodexDriverConfig } from './driver-config.ts'
import { CodexDriverInteractions } from './driver-interactions.ts'
import { projectDriverEvent } from './driver-output.ts'
import { CodexProtocolError } from './rpc-types.ts'
import type { CodexAppServerEvent, CodexTurnOutcome, CodexTurnRef, CodexTurnSubmission } from './session-types.ts'
import type { CodexThreadSession } from './thread-session.ts'
import { AttachmentFailure, assertSerializedAttachments, prepareAttachments, snapshotInput, validCanonicalInput, validateAttachments } from '../provider-session-io/attachments.ts'
import { exactMcpPolicyReady, requiredMcpToolsReady } from './mcp-status.ts'

const failure = (code: FailureCode, unsent = false) => ({ ok: false as const, code, ...(unsent ? { delivery: 'known-not-sent' as const } : {}) })
type Pending = { input: Input; ownerKey: string; receipt: ReturnType<typeof deferred<Reply<Handoff>>>; abort: AbortController; revoked: boolean; earlyBytes: number;
  capture?: CodexInputWindowCapture; turn?: CodexTurnSubmission; ref?: CodexTurnRef; outcome?: CodexTurnOutcome; early: CodexAppServerEvent[] }
const isKnownUnsent = (owner: Pending, error: unknown): boolean => !owner.turn || (error instanceof CodexProtocolError && error.acceptance === 'not-sent')
type Control = Reply<{ requested: true; terminal: 'unconfirmed' }>
const outcome = (native: CodexTurnOutcome): Extract<EventPayload, { kind: 'result' }> => ({ kind: 'result',
  outcome: native.outcome === 'completed' ? 'succeeded' : native.outcome === 'interrupted' ? 'cancelled' : native.outcome === 'failed' ? 'failed' : 'unknown',
  ...(native.outcome === 'failed' ? { code: 'provider-failure' as const } : {}) })

/** Volatile provider protocol state only. No process, durable input or product-state ownership. */
export class CodexDriverSession implements Session {
  readonly sessionRef: string
  private readonly config: CodexDriverConfig
  private readonly client: CodexAppServerClient
  private readonly feed: EventFeed<Event>
  private readonly interactions: CodexDriverInteractions
  private readonly queued: Pending[] = []
  private readonly nativeItemOwners = new Map<string, string | null>()
  private nativeItemBytes = 0
  private legacyItemsExhausted = false
  private readonly abort = new AbortController()
  private thread: CodexThreadSession | undefined
  private active: Pending | undefined
  private state: 'open' | 'unavailable' | 'closed' = 'open'
  private control: Promise<Control> | undefined
  private closing: Promise<CloseReceipt> | undefined
  private turnBytes = 0
  private turnEvents = 0
  /** Auxiliary native sample has no authority over normal turn, queue or lifecycle. */
  private sampleAbort: AbortController | undefined
  private sampleRevision = 0
  constructor(config: CodexDriverConfig, restored?: CodexDriverCheckpoint) {
    this.config = config; this.sessionRef = config.binding.sessionId
    for (const [item, owner] of restored?.itemOwners ?? []) {
      this.nativeItemOwners.set(item, owner); this.nativeItemBytes += Buffer.byteLength(item) + (owner === null ? 0 : Buffer.byteLength(owner))
    }
    this.legacyItemsExhausted = restored?.legacyItemsExhausted ?? false
    this.feed = new EventFeed(config.limits.outputEvents, config.limits.outputBytes)
    this.interactions = new CodexDriverInteractions(config.limits.pendingInteractions, (event, owner) => {
      if (owner === this.active && !this.active.revoked) {this.emit(event, this.active)}
    })
    this.client = new CodexAppServerClient({ transport: config.transport,
      limits: { ...config.rpcLimits, requestTimeoutMs: Math.min(config.rpcLimits?.requestTimeoutMs ?? config.limits.timeoutMs, config.limits.timeoutMs) }, maxThreads: 1,
      maxQueuedTurns: 1, maxBufferedNotifications: 64, maxTextBytes: config.limits.outputBytes,
      onEvent: event => { this.nativeEvent(event) }, onItem: (ref, itemId) => { this.rememberNativeItem(ref, itemId) }, requestApproval: async (request, signal) => {
        const owner = this.active
        if (!owner || !this.acceptsInteraction(owner)) {throw new Error('codex.driver.stale-interaction')}
        const ref = await owner.turn?.accepted
        if (!ref || signal.aborted || !this.acceptsInteraction(owner)) {throw new Error('codex.driver.stale-interaction')}
        if (request.turnId === null && (this.legacyItemsExhausted || request.itemId === null || request.itemId.length === 0 || this.nativeItemOwners.get(request.itemId) !== owner.ownerKey)) {
          this.emit({ kind: 'diagnostic', code: this.legacyItemsExhausted ? 'output-limit' : 'unsupported' }, owner)
          throw new Error('codex.driver.ambiguous-legacy-item')
        }
        return this.interactions.request(request, signal, owner)
      } })
  }
  async open(nativeThread?: string): Promise<void> {
    await this.client.initialize(this.config.initialize)
    if (this.config.mcpPolicy && (!await bounded(this.config.verifyMcpCatalog!(this.abort.signal), this.config.limits.timeoutMs) || !await this.client.matchesMcpConfiguration(this.config.mcpPolicy, this.abort.signal))) { throw new Error('codex.driver.mcp-policy-mismatch') }
    this.thread = nativeThread === undefined ? await this.client.startThread(this.config.threadParams) : await this.client.resumeThread(nativeThread, this.config.threadParams)
  }
  submit(supplied: Input): Promise<Reply<Handoff>> {
    if (this.state !== 'open') {return Promise.resolve(failure('unavailable', true))}
    let input: Input
    try { input = snapshotInput(supplied); validateAttachments(input, 'codex', typeof this.config.threadParams.model === 'string' ? this.config.threadParams.model : undefined, this.config.attachments) }
    catch (error) { return Promise.resolve(failure(error instanceof AttachmentFailure ? error.code : 'invalid-config', true)) }
    if (!validCanonicalInput(input, this.config.limits.inputBytes))
      {return Promise.resolve(failure('invalid-config', true))}
    if (this.active?.input.inputId === input.inputId || this.active?.input.operationRef === input.operationRef
      || this.queued.some(item => item.input.inputId === input.inputId || item.input.operationRef === input.operationRef)) {return Promise.resolve(failure('stale', true))}
    if (this.queued.length >= this.config.limits.queuedInputs) {return Promise.resolve(failure('backpressure', true))}
    const pending: Pending = { input, ownerKey: randomUUID(), receipt: deferred(), abort: new AbortController(), revoked: false, early: [], earlyBytes: 0 }
    this.invalidateSample()
    this.queued.push(pending); this.advance(); return pending.receipt.promise
  }
  observe(): AsyncIterable<Event> { return this.feed }
  async checkReadiness(): Promise<Reply<void>> {
    if (this.state !== 'open' || !this.client.isOpen()) {return failure('unavailable')}
    const deadline = new AbortController()
    try {
      const signal = AbortSignal.any([deadline.signal, this.abort.signal])
      const ready = await bounded((async () => {
        if (this.config.mcpPolicy) {
          const policy = this.config.mcpPolicy
          if (!this.thread || !await this.config.verifyMcpCatalog!(signal) || !await this.client.matchesMcpConfiguration(policy, signal) ||
            !await exactMcpPolicyReady(this.client, this.thread.threadId, { selected: Object.keys(policy.selected), disabled: policy.catalog.servers.filter(row => !Object.hasOwn(policy.selected, row.name)).map(row => row.name), required: this.config.requiredMcpTools ?? {} }, signal)) { return false }
        }
        if (!this.config.mcpPolicy && this.config.requiredMcpTools && Object.keys(this.config.requiredMcpTools).length > 0 &&
          (!this.thread || !await requiredMcpToolsReady(this.client, this.thread.threadId, this.config.requiredMcpTools, signal))) { return false }
        return this.config.probe(signal)
      })(), this.config.limits.timeoutMs)
      return ready && this.isUsable() ? { ok: true, value: undefined } : failure('dependency-unavailable')
    } catch { return failure('dependency-unavailable') } finally { deadline.abort() }
  }
  respondToInteraction(ref: string, reply: InteractionReply): Reply<void> {
    if (this.state !== 'open' || this.active?.revoked === true || this.control) {return failure('stale')}
    return this.interactions.respond(ref, reply, this.active)
  }
  interrupt(operationRef: string): Promise<Control> {
    const owner = this.active
    if (this.state !== 'open' || !owner || owner.input.operationRef !== operationRef || !owner.turn) {return Promise.resolve(failure('stale'))}
    if (this.control) {return this.control}
    owner.revoked = true
    this.control = (async (): Promise<Control> => {
      try {
        const target = await owner.turn!.accepted
        if (this.state !== 'open' || this.active !== owner || owner.outcome) {return failure('stale')}
        await this.thread!.interrupt(target)
        return { ok: true, value: { requested: true, terminal: 'unconfirmed' } }
      } catch {
        if (owner.outcome) {return failure('stale')}
        this.seal('unknown'); return failure('unknown')
      }
    })()
    void this.control.finally(() => { this.control = undefined; this.advance() })
    return this.control
  }
  checkpoint(): Reply<unknown> {
