const readinessObservation = (() => {
  let diagnostic: ReturnType<typeof channel> | undefined;
  let identity: { schemaVersion: 1; bindingDigest: string; sourceId: string; sourceRevision: string } | undefined;
  let sequence = 0, invocations = 0, disabled = false;
  try {
    diagnostic = channel('agent-teams.legacy-host.codex-readiness');
    const origin = context.processOrigin, binding = context.endpoint.binding;
    const sourceId = origin?.sourceId, sourceRevision = origin?.revision;
    if (origin?.origin.kind === 'runtime' && typeof sourceId === 'string' && /^[a-f0-9]{64}$/.test(sourceId) &&
        typeof sourceRevision === 'string' && /^[a-f0-9]{64}$/.test(sourceRevision)) {
      const { backendId, teamId, runId, memberId, generation } = binding;
      if ([backendId, teamId, runId, memberId, generation].every(value => typeof value === 'string'))
        identity = { schemaVersion: 1, bindingDigest: managementDigest({ backendId, teamId, runId, memberId, generation }), sourceId, sourceRevision };
    }
  } catch { disabled = true; }
  const limit = (): void => { try {
    if (!identity || disabled) return; disabled = true;
    if (diagnostic?.hasSubscribers) diagnostic.publish({ ...identity, limit: true });
  } catch { disabled = true; } };
  const publish = (invocation: number | undefined, operation: ReadinessOperation, phase: ReadinessPhase, result: boolean | null = null): void => { try {
    if (!identity || disabled || invocation === undefined) return;
    if (sequence >= 64) { limit(); return; }
    sequence++;
    if (diagnostic?.hasSubscribers) diagnostic.publish({ ...identity, sequence, invocation, operation, phase, result });
  } catch { disabled = true; } };
  const begin = (operation: ReadinessOperation): number | undefined => { try {
    if (!identity || disabled) return undefined;
    if (invocations >= 16) { limit(); return undefined; }
    const invocation = ++invocations; publish(invocation, operation, 'before-await'); return invocation;
  } catch { disabled = true; return undefined; } };
  return { begin, publish };

const verifyCatalog = async (signal?: AbortSignal): Promise<boolean> => {
  if (!policy) return true;
  let invocation: number | undefined;
  const assertCurrent = () => {
    if (sealed || !context.isCurrent() || !capturedMcpSourceCurrent(profile))
      throw new Error('Captured MCP authority changed');
  };
  try {
    assertCurrent();
    invocation = readinessObservation.begin('catalog');
    const actual = await (options.readCatalog ?? readCodexMcpCatalog)(
      profile,
      assertCurrent,
      signal,
      capturedNativeProcessFactory(context.retainedWindowsLaunch, context.processOrigin)
    );
    readinessObservation.publish(invocation, 'catalog', 'after-await');
    assertCurrent();
    const matches = actual.digest === policy.catalog.digest;
    readinessObservation.publish(invocation, 'catalog', 'returned', matches);
    return matches;
  } catch {
    readinessObservation.publish(invocation, 'catalog', 'threw');
    return false;
  }

const factory: DriverFactory = {
  async open(request) {
    let invocation: number | undefined;
    try {
      invocation = readinessObservation.begin('open');
      const opened = await native.open(request);
      readinessObservation.publish(invocation, 'open', 'after-await');
      const source = opened.driver;
      const driver: Session = {
        sessionRef: source.sessionRef,
        submit: (input) => source.submit(input),
        async *observe() {
          for await (const event of source.observe()) {
            yield event;
            context.onProgress();
          }
        },
        respondToInteraction: (reference, reply) => source.respondToInteraction(reference, reply),
        interrupt: (operation) => source.interrupt(operation),
        async checkReadiness() {
          const invocation = readinessObservation.begin('readiness');
          try {
            const proof = await source.checkReadiness();
            readinessObservation.publish(invocation, 'readiness', 'after-await');
            ready = proof.ok && current();
            readinessObservation.publish(invocation, 'readiness', 'returned', ready);
            return proof;
          } catch (error) {
            readinessObservation.publish(invocation, 'readiness', 'threw');
            throw error;
          }

return { async open(request) {
  const selected = Object.freeze({ ...request, requiredCapabilities: Object.freeze([...request.requiredCapabilities]) })
  if (selected.requiredCapabilities.some(value => !capabilities.includes(value))) {throw new Error('codex.driver.unsupported')}
  let config: CodexDriverConfig
  try { const value = await host.resolveConfiguration(selected); if (!value) {throw new Error('missing');} config = captureDriverConfig(value, selected) }
  catch { throw new Error('codex.driver.invalid-config') }
  let restored: CodexDriverCheckpoint | undefined
  if (selected.checkpointRef !== undefined) {
    let checkpoint: unknown
    try { checkpoint = await host.readCheckpoint(selected.checkpointRef, selected) } catch { throw new Error('codex.driver.checkpoint-missing') }
    if (checkpoint === undefined) {throw new Error('codex.driver.checkpoint-missing')}
    restored = selectedDriverCheckpoint(checkpoint, config)
  }
  const driver = new CodexDriverSession(config, restored)
  const mandatoryNativeTools = Object.keys(config.requiredMcpTools ?? {}).length > 0 || config.mcpPolicy !== undefined
  try {
    if (!mandatoryNativeTools) {
      const ready = await driver.checkReadiness()
      if (!ready.ok) {throw new Error('codex.driver.' + ready.code)}
    }
    await driver.open(restored?.nativeThreadId)
  } catch { await driver.close(); throw new Error('codex.driver.open-failed') }
  // Thread-scoped discovery requires the owned native thread. No turn/work is
  // submitted until native mandatory tools and the Host probe both pass.
  if (mandatoryNativeTools) {
    const ready = await driver.checkReadiness()
    if (!ready.ok) { await driver.close(); throw new Error('codex.driver.' + ready.code) }

async open(nativeThread?: string): Promise<void> {
  await this.client.initialize(this.config.initialize)
  if (this.config.mcpPolicy && (!await bounded(this.config.verifyMcpCatalog!(this.abort.signal), this.config.limits.timeoutMs) || !await this.client.matchesMcpConfiguration(this.config.mcpPolicy, this.abort.signal))) { throw new Error('codex.driver.mcp-policy-mismatch') }
  this.thread = nativeThread === undefined ? await this.client.startThread(this.config.threadParams) : await this.client.resumeThread(nativeThread, this.config.threadParams)

async checkReadiness(): Promise<Reply<void>> {
  if (this.state !== 'open' || !this.client.isOpen()) {return failure('unavailable')}
  const deadline = new AbortController()
  try {
    const signal = AbortSignal.any([deadline.signal, this.abort.signal])
    const ready = await bounded((async () => {
      if (this.config.mcpPolicy) {
        const policy = this.config.mcpPolicy
        if (!this.thread || !await this.config.verifyMcpCatalog!(signal) || !await this.client.matchesMcpConfiguration(policy, signal) ||
          !await exactMcpPolicyReady(this.client, this.thread.threadId, { selected: Object.keys(policy.selected), disabled: policy.catalog.servers.filter(row => !Object.hasOwn(policy.selected, row.name)).map(row => row.name), required: this.config.requiredMcpTools ?? {} }, signal)) { return false }
      }
      if (!this.config.mcpPolicy && this.config.requiredMcpTools && Object.keys(this.config.requiredMcpTools).length > 0 &&
        (!this.thread || !await requiredMcpToolsReady(this.client, this.thread.threadId, this.config.requiredMcpTools, signal))) { return false }
      return this.config.probe(signal)
    })(), this.config.limits.timeoutMs)
    return ready && this.isUsable() ? { ok: true, value: undefined } : failure('dependency-unavailable')
  } catch { return failure('dependency-unavailable') } finally { deadline.abort() }

const { entry, record, binding } = options;
const observed = options.runtime.readSession(binding);
const bindingMatches = runtimeDigest(binding) === runtimeDigest(entry.binding);
let recordReady: boolean | null = null, providerReady: boolean | null = null, ownerCurrent: boolean | null = null;
const nativeReady =
  bindingMatches &&
  (recordReady = !!record?.nativeReady) &&
  (providerReady = !!entry.provider?.isReady()) &&
  (ownerCurrent = options.isCurrent());

try {
  assertAuthority?.();
  const opened = await this.options.driverFactory.open(config, assertAuthority);
  this.drivers.set(this.key(binding), opened.driver);
  if (
    typeof opened.driver.sessionRef !== 'string' ||
    !opened.driver.sessionRef ||
    opened.driver.sessionRef.length > 1024
  )
    throw new RuntimeOwnerError('hold');
  let record = this.publish(binding, (current) => {
    if (!this.options.authorize(binding, 'admit') || !this.authorityCurrent(assertAuthority)) current.sealed = true;
    current.sessionRef = opened.driver.sessionRef;
    current.custody = 'owned';
    current.phase = current.sealed ? 'closing' : 'allocated';
  });
  void this.observe(binding, opened.driver);
  if (record.sealed) return await this.stopOwned(binding, true);
  const ready = await opened.driver.checkReadiness();
  record = this.publish(binding, (current) => {
    if (current.phase !== 'allocated' || current.sealed) return;
    current.nativeReady =
      ready.ok &&
      config.requiredCapabilities.every((capability) =>
        opened.capabilities.includes(capability)
      );
    if (!current.nativeReady) current.diagnostic = 'readiness-unavailable';
  });
  return record;
} catch {
  return this.publish(binding, (current) => {
    if (current.phase === 'closed') return;
    current.phase = 'held';
    current.nativeReady = false;
    current.custody = 'unknown';
    current.diagnostic = 'open-unknown';
  });

try { channel('agent-teams.legacy-host.runtime-projection').subscribe(value => { try {
  if (codexUnknown) return;
  const tuple = codexTuple(value, ['viewDigest', 'bindingMatches', 'recordReady', 'providerReady', 'ownerCurrent', 'nativeReady']);
  assert.ok(typeof tuple[0] === 'string' && /^[a-f0-9]{64}$/.test(tuple[0]));
  assert.equal(typeof tuple[1], 'boolean'); assert.equal(typeof tuple[5], 'boolean');
  for (let index = 2; index <= 4; index++)
    assert.ok(tuple.slice(1, index).every(value => value === true) ? typeof tuple[index] === 'boolean' : tuple[index] === null);
  assert.equal(tuple[5], tuple.slice(1, 5).every(value => value === true));
  assert.ok(codexViews.has(tuple[0]) || codexViews.size < 4); codexViews.set(tuple[0], codexEvents.length);
} catch { codexReject(); } }); } catch { codexReject(); }
try { process.once('exit', () => { try {
  const value = codexUnknown ? { schemaVersion: 1, status: 'unknown', reason: 'invalid-overflow-or-observer-failure' }
    : { schemaVersion: 1, status: 'observed', contexts: codexContexts, events: codexEvents, views: [...codexViews] };
  const raw = JSON.stringify(value);
  writeFileSync(projectionLedger + '.codex-readiness', Buffer.byteLength(raw) <= 8192 ? raw :
    '{"schemaVersion":1,"status":"unknown","reason":"invalid-overflow-or-observer-failure"}', { mode: 0o600, flag: 'wx' });
} catch { /* A missing separate ledger remains unknown; preserve the original exit listener. */ } }); } catch { codexReject(); }

const input = object(options), projection = object(input.runtimeProjection), launch = object(input.lastLaunchReadiness);
assert.equal(input.provider, 'codex'); assert.equal(typeof input.ledgerPath, 'string'); assert.ok(input.ledgerPath.length > 0);
assert.ok(Array.isArray(input.epochs) && input.epochs.length === 1);
const epoch = object(input.epochs[0]), source = object(launch.source), last = object(launch.lastRuntimeRead);
assert.equal(epoch.projectionHostExit, 'confirmed');
for (const id of [epoch.mainEpoch, launch.launchId]) assert.ok(typeof id === 'string' && id.length >= 1 && id.length <= 256 && !id.includes('\0'));
for (const digest of [source.sourceId, source.revision, input.lastRuntimeViewDigest])
  assert.ok(typeof digest === 'string' && /^[a-f0-9]{64}$/.test(digest));
assert.equal(Object.keys(source).sort().join(' '), 'revision sourceId');
assert.equal(Object.keys(projection).sort().join(' '), 'atomicWithFailure bindingMatches nativeReady ownerCurrent providerReady recordReady status viewDigest');
assert.equal(projection.status, 'observed'); assert.equal(projection.atomicWithFailure, false);
assert.equal(projection.viewDigest, input.lastRuntimeViewDigest); assert.equal(last.viewDigest, input.lastRuntimeViewDigest);
const readiness = [projection.bindingMatches, projection.recordReady, projection.providerReady, projection.ownerCurrent, projection.nativeReady];
assert.equal(typeof readiness[0], 'boolean'); assert.equal(typeof readiness[4], 'boolean');
for (let index = 1; index <= 3; index++)
  assert.ok(readiness.slice(0, index).every(value => value === true) ? typeof readiness[index] === 'boolean' : readiness[index] === null);
assert.equal(readiness[4], readiness.slice(0, 4).every(value => value === true)); assert.equal(readiness[0], true);
assert.ok(Array.isArray(input.diagnosticLaunches));
const launches = input.diagnosticLaunches.map(object).filter(row => row.launchId === launch.launchId); assert.equal(launches.length, 1);
const selected = launches[0]; assert.ok(selected);
const selectedSource = object(selected.source); assert.deepEqual(selectedSource, source);
assert.ok(Array.isArray(selected.bindingDigests) && selected.bindingDigests.length > 0);
assert.ok(selected.bindingDigests.every(value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value)));
assert.equal(new Set(selected.bindingDigests).size, selected.bindingDigests.length);
const stat = lstatSync(input.ledgerPath); assert.ok(stat.isFile() && !stat.isSymbolicLink() && stat.size >= 0 && stat.size <= 8192);
const raw = readFileSync(input.ledgerPath, 'utf8'); assert.ok(Buffer.byteLength(raw) <= 8192);

const matches = contexts.map((tuple, index) => ({ tuple, index })).filter(({ tuple }) =>
  selected.bindingDigests.includes(tuple[0]) && tuple[1] === source.sourceId && tuple[2] === source.revision);
assert.equal(matches.length, 1); const context = matches[0]; assert.ok(context);
const matchingViews = views.filter(tuple => tuple[0] === input.lastRuntimeViewDigest);
assert.equal(matchingViews.length, 1); const view = matchingViews[0]; assert.ok(view);
const observedEventCount = view[1];
const result = { schemaVersion: 1, status: 'observed', atomicWithFailure: false,
  samplePoint: 'last-original-projection-with-matching-view-digest',
  source: { sourceId: source.sourceId, revision: source.revision }, bindingDigest: context.tuple[0], viewDigest: view[0],
  mainEpoch: epoch.mainEpoch, launchId: launch.launchId, observedEventCount,
  events: events.slice(0, observedEventCount).filter(tuple => tuple[0] === context.index).map(tuple => tuple.slice(1)) };
assert.ok(Buffer.byteLength(JSON.stringify(result)) <= 8192); return result;

let view: Record<string, unknown> = {};
const readiness = { source: sourceRef(source), image, launchId, readCount: 0, elapsedMs: 0,
  lastRuntimeRead: null as Record<string, unknown> | null };
evidence.lastLaunchReadiness = readiness;
const readinessStarted = performance.now();
try {
  await poll(async () => { view = await first.rpc(team, 'runtime.read', `TEST-ready-${image}`, { memberId: 'alice-id' });
    try { lastRuntimeViewDigest = runtimeDigest(view); } catch { lastRuntimeViewDigest = undefined; }
    Object.assign(readiness, { readCount: readiness.readCount + 1, elapsedMs: performance.now() - readinessStarted,
      lastRuntimeRead: { viewDigest: lastRuntimeViewDigest ?? null, memberId: view.memberId, generation: view.generation, phase: view.phase,
        sealed: view.sealed, custody: view.custody, nativeReady: view.nativeReady, attached: view.attached,
        ...(view.diagnostic === undefined ? {} : { diagnostic: view.diagnostic }) } });
    return view.nativeReady === true; }, 'Original source Team readiness');
} finally {
  console.log(JSON.stringify({ kind: 'TEST_SOURCE_READINESS', provider, ...readiness }));
}

// TEST_RUNTIME_PROJECTION_READER_BEGIN
if (failure) try {
  assert.equal(epochs.length, 1);
  assert.equal(epochs[0]?.projectionHostExit, 'confirmed');
  const stat = lstatSync(fixture.runtimeProjectionLedger);
  assert.ok(stat.isFile() && !stat.isSymbolicLink() && stat.size <= 512);
  const raw = readFileSync(fixture.runtimeProjectionLedger, 'utf8'); assert.ok(Buffer.byteLength(raw) <= 512);
